#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

#define BITSET_BYTES  1024

char idx[BITSET_BYTES];
uint16_t fold_size;
uint16_t fold_mask; // Fast 6502 mask: fold_size - 1

uint16_t hash_trigram(char* s) {
  uint16_t h = 0;
  char a = s[0], b = s[1], c = s[2];
  if (!isalnum(a) || !isalnum(b) || ((a|b|c)&0x80)) return 0;
  if (!isalnum(c)) c = 0;
  h = (tolower(a) << 4) ^ tolower(b);
  if (c) { h = (h << 4) ^ tolower(c); }
  return h & 0x1FFF;
}

uint16_t hash_unigram(char* s, unsigned char len) {
  uint16_t h = 5381;
  while (len--) h = ((h << 3) + h) ^ tolower(*s++);
  return h & 0x1FFF;
}

uint16_t hash_bigram(uint16_t h1, uint16_t h2) {
  uint16_t h = (h1 << 3) | (h1 >> 10);
  return (h ^ h2) & 0x1FFF;
}

// Clean, simple, and hyper-optimized for the 6502
char test_bit(uint16_t h) {
  uint16_t i = (h >> 3) & fold_mask;
  return (idx[i] & (1 << (h & 7))) ? 1 : 0;
}

void pr_case(char* s, int len, char found) {
  int i;
  for (i = 0; i < len; i++) {
    putchar(found ? tolower(s[i]) : toupper(s[i]));
  }
}

int main(int argc, char* argv[]) {
  FILE* f;
  long sz;
  int i, j;
  uint16_t hits = 0, total = 0;
  uint16_t whash = 0, last_whash = 0;
  char first_word = 1;

  if (argc < 3) {
    printf("Usage: search <idx_file> <word1> [word2] ...\n");
    return 1;
  }

  if (!(f = fopen(argv[1], "rb"))) {
    printf("%%Error opening %s\n", argv[1]);
    return 1;
  }

  sz = fread(idx, 1, BITSET_BYTES, f);
  fclose(f);

  if (sz > BITSET_BYTES || sz < 32) {
    printf("%%Error: Invalid index size %ld\n", sz);
    return 1;
  }

  fold_size = (uint16_t)sz;
  fold_mask = fold_size - 1; // Compute mask once to bypass division/modulo loops

  printf("Search:\t");
  
  // --- PASS 1: WORD EVALUATION & STREAM GENERATION ---
  for (i = 2; i < argc; i++) {
    char* p = argv[i];
    char* wstart = p;
    unsigned char wlen = 0;
    char found, both;
    uint16_t bothhash;

    while (1) {
      if (isalnum(*p)) {
        if (!wlen) wstart = p;
        wlen++;
      } else if (wlen > 0) {
	whash = hash_unigram(wstart, wlen);
	total++;
	found = test_bit(whash);
	if (found) hits++;
	
	both = 0;
	if (!first_word) {
	  if (last_whash) {
	    bothhash = hash_bigram(last_whash, whash);
	    total++;
	    if (test_bit(bothhash)) { hits++; both = 1; }
	  }
	  putchar(both ? '_' : ' ');
	}
	first_word = 0;

	pr_case(wstart, wlen, found);
	
	last_whash = whash;
	wlen = 0;
      }

      if (!*p) break;

      p++;
    }
  }

  // --- PASS 2: TRIGRAM EVALUATION LINE ---
  printf("\nTriNot:\t");
  for (i = 2; i < argc; i++) {
    char* w = argv[i];
    int len = strlen(w);
    if (len >= 3) {
      for (j = 0; j <= len - 3; j++) {
        uint16_t thash = hash_trigram(&w[j]);
        if (thash) {
          char tok = 0;
          total++;
          if (test_bit(thash)) { hits++; tok = 1; }
          if (!tok) pr_case(&w[j], 3, tok),putchar(' ');
        }
      }
    }
  }

  uint16_t pct = total ? (uint16_t)(((unsigned long)hits * 100) / total) : 0;
  printf("\nMatch:\t%u%%\n", pct);

  return 0;
}
